% Initialize a data struct for one apartment unit.
oneAptUnit  = []; 

% Living Room
oneAptUnit   = addRoomToFloorPlan(FloorPlan=oneAptUnit,...
    NewRoom="LivingRoom",...
    Vertex=simscape.Value([0.4,0.1],"ft"),...
    Length=simscape.Value(7.99,"ft"),...
    Width=simscape.Value(9.98,"ft"));

% Bedroom
oneAptUnit   = addRoomToFloorPlan(FloorPlan=oneAptUnit,...
    NewRoom="Bedroom",...
    Vertex=simscape.Value([10.2,-2],"ft"),...
    Length=simscape.Value(14,"ft"),...
    Width=simscape.Value(10,"ft"));
% Kitchen
oneAptUnit   = addRoomToFloorPlan(FloorPlan=oneAptUnit,...
    NewRoom="Kitchen",...
    Vertex=simscape.Value([1.4,-5.9],"ft"),...
    Length=simscape.Value(6,"ft"),...
    Width=simscape.Value(8,"ft"));
% Bathroom
oneAptUnit   = addRoomToFloorPlan(FloorPlan=oneAptUnit,...
    NewRoom="Bathroom",...
    Vertex=simscape.Value([3,8],"ft"),...
    Length=simscape.Value(5,"ft"),...
    Width=simscape.Value(7,"ft"));

% Fire Exit
oneAptUnit   = addRoomToFloorPlan(FloorPlan=oneAptUnit,... %[output:group:5385e6f3] %[output:2e3643c0]
    NewRoom="FireExit",... %[output:2e3643c0]
    Vertex=simscape.Value([-2.1,-5],"ft"),... %[output:2e3643c0]
    Length=simscape.Value(5,"ft"),... %[output:2e3643c0]
    Width=simscape.Value(4,"ft"),... %[output:2e3643c0]
    Plot=true); %[output:group:5385e6f3] %[output:2e3643c0]

oneAptUnit_edited = adjustRoomContact(Apartment=oneAptUnit,MaxIter=10000,Tol=2,Plot=true); %[output:0f512d86]


